"""Usage: embed.py <output.h> <file>...

Compiles the Customize page's files into a header (argon_customize_ui.cc
serves them), so the page needs no grit, pak or resource ids. The first file
is the one served for unknown paths."""

import os
import sys

out, files = sys.argv[1], sys.argv[2:]
lines = [
    '// Generated by resources/embed.py. Do not edit.',
    '#ifndef CHROME_BROWSER_UI_VIEWS_ARGON_ARGON_CUSTOMIZE_RESOURCES_H_',
    '#define CHROME_BROWSER_UI_VIEWS_ARGON_ARGON_CUSTOMIZE_RESOURCES_H_',
    '',
    '#include <array>',
    '#include <cstdint>',
    '#include <string_view>',
    '',
    '#include "base/containers/span.h"',
    '',
    'namespace argon {',
    '',
    'struct CustomizeFile {',
    '  std::string_view path;',
    '  base::span<const uint8_t> data;',
    '};',
    '',
]
for i, path in enumerate(files):
  with open(path, 'rb') as f:
    data = f.read()
  lines.append(f'inline constexpr uint8_t kCustomizeFile{i}[] = {{')
  for j in range(0, len(data), 16):
    lines.append('    ' + ', '.join(str(b) for b in data[j:j + 16]) + ',')
  lines.append('};')
lines.append('')
lines.append('inline constexpr auto kCustomizeFiles = std::to_array<CustomizeFile>({')
for i, path in enumerate(files):
  lines.append(f'    {{"{os.path.basename(path)}", kCustomizeFile{i}}},')
lines += [
    '});',
    '',
    '}  // namespace argon',
    '',
    '#endif  // CHROME_BROWSER_UI_VIEWS_ARGON_ARGON_CUSTOMIZE_RESOURCES_H_',
    '',
]
with open(out, 'w') as f:
  f.write('\n'.join(lines))
